    source_color, cells = guide
    rs = [r for r, c in cells]
    cs = [c for r, c in cells]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)

    # Determine the corner and the directions of the two arms of an L.
    corner = None
