                if (c == cc and (r-cr)*(-vdir) > 0) or
                   (r == cr and (c-cc)*(-hdir) > 0)
            )
            if hits:
                ray_choices.append((hits, color, obj))
        if ray_choices:
            _, color, target = max(ray_choices, key=lambda x: x[0])
        else:
            # Otherwise choose the nearest component in the quadrant opposite
            # the two arms.
            candidates = []
            for color, obj in comps:
                if color == source_color:
                    continue
                mr = sum(r for r, c in obj) / len(obj)
                mc = sum(c for r, c in obj) / len(obj)
                dr, dc = mr-cr, mc-cc
                if dr*(-vdir) >= 0 and dc*(-hdir) >= 0:
                    candidates.append((dr*dr + dc*dc, color, obj))
            if candidates:
                _, color, target = min(candidates, key=lambda x: x[0])

    if target:
        for r, c in target:
            g[r][c] = source_color
    return g
